package com.hollingsworth.arsnouveau.api.registry;

import com.hollingsworth.arsnouveau.api.ritual.AbstractRitual;
import com.hollingsworth.arsnouveau.common.items.RitualTablet;
import net.minecraft.resources.ResourceLocation;

import javax.annotation.Nullable;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class RitualRegistry {

    private static ConcurrentHashMap<ResourceLocation, AbstractRitual> ritualMap = new ConcurrentHashMap<>();

    private static ConcurrentHashMap<ResourceLocation, RitualTablet> ritualItemMap = new ConcurrentHashMap<>();

    public static @Nullable AbstractRitual getRitual(ResourceLocation id) {
        if (!ritualMap.containsKey(id))
            return null;
        try {
            return ritualMap.get(id).getClass().getDeclaredConstructor().newInstance();
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }

    public static Map<ResourceLocation, AbstractRitual> getRitualMap() {
        return ritualMap;
    }

    public static Map<ResourceLocation, RitualTablet> getRitualItemMap() {
        return ritualItemMap;
    }

    public static AbstractRitual registerRitual(AbstractRitual ritual) {
        return ritualMap.put(ritual.getRegistryName(), ritual);
    }
}

package com.hollingsworth.arsnouveau.api.ritual;

import com.hollingsworth.arsnouveau.ArsNouveau;
import com.hollingsworth.arsnouveau.api.util.BlockUtil;
import com.hollingsworth.arsnouveau.client.particle.ParticleColor;
import com.hollingsworth.arsnouveau.common.block.tile.RitualBrazierTile;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.RandomSource;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.ItemLike;
import net.minecraft.world.level.Level;
import org.jetbrains.annotations.NotNull;

import javax.annotation.Nullable;
import java.util.*;
import java.util.function.Predicate;

public abstract class AbstractRitual {

    public RitualBrazierTile tile;

    private RitualContext context;

    public RandomSource rand = RandomSource.create();

    public UUID playerUUID;

    public AbstractRitual() {
    }

    public void tryTick(RitualBrazierTile tickingTile) {
        if (tickingTile == null || !getContext().isStarted || getContext().isDone) {
            return;
        }
        this.tile = tickingTile;
        tick();
    }

    public @Nullable BlockPos getPos() {
        return tile != null ? tile.getBlockPos() : null;
    }

    public @Nullable Level getWorld() {
        return tile != null ? tile.getLevel() : null;
    }

    public boolean canStart(@Nullable Player player) {
        return true;
    }

    public List<ItemStack> getConsumedItems() {
        return getContext().consumedItems;
    }

    public boolean canConsumeItem(ItemStack stack) {
        return false;
    }

    public void onItemConsumed(ItemStack stack) {
        this.getConsumedItems().add(stack.split(1));
        BlockUtil.safelyUpdateState(getWorld(), tile.getBlockPos());
    }

    public boolean didConsumeItem(ItemLike item) {
        for (ItemStack i : getConsumedItems()) {
            if (i.getItem() == item.asItem())
                return true;
        }
        return false;
    }

    public int itemConsumedCount(Predicate<ItemStack> stackPredicate) {
        int total = 0;
        for (ItemStack stack : getConsumedItems()) {
            if (stackPredicate.test(stack)) {
                total += stack.getCount();
            }
        }
        return total;
    }

    /**
     * Returns the list of consumed items in Item x Num format. Because rituals can consume above the itemstack count, stacks are also stored as unique entries.
     */
    public List<String> getFormattedConsumedItems() {
        Map<String, Integer> map = new HashMap<>();
        for (ItemStack i : getConsumedItems()) {
            String name = i.getHoverName().getString();
            if (map.containsKey(name)) {
                map.put(name, map.get(name) + 1);
            } else {
                map.put(name, 1);
            }
        }
        List<String> list = new ArrayList<>();
        for (String s : map.keySet()) {
            list.add(s + " x " + map.get(s));
        }
        return list;
    }

    public void incrementProgress() {
        getContext().progress++;
    }

    public int getProgress() {
        return getContext().progress;
    }

    public void onStart(@Nullable Player player) {
        getContext().isStarted = true;
        if (player != null) this.playerUUID = player.getUUID();
    }

    public boolean isRunning() {
        return getContext().isStarted && !getContext().isDone;
    }

    public boolean isDone() {
        return getContext().isDone;
    }

    public void setFinished() {
        getContext().isDone = true;
    }

    protected abstract void tick();

    public void onEnd() {
        this.getContext().isDone = true;
    }

    public String getName() {
        return Component.translatable(ArsNouveau.MODID + ".tablet_of", Component.translatable("item." + getRegistryName().getNamespace() + "." + getRegistryName().getPath()).getString()).getString();
    }

    public String getDescription() {
        return Component.translatable(getDescriptionKey()).getString();
    }

    public String getDescriptionKey() {
        return getRegistryName().getNamespace() + ".ritual_desc." + getRegistryName().getPath();
    }

    public int getSourceCost() {
        return 0;
    }

    public boolean consumesSource() {
        return getSourceCost() > 0;
    }

    public void setNeedsSource(boolean needMana) {
        getContext().needsSourceToRun = needMana;
        BlockUtil.safelyUpdateState(getWorld(), tile.getBlockPos());
    }

    public boolean needsSourceNow() {
        return getContext().needsSourceToRun;
    }

    public boolean takeSourceNow() {
        setNeedsSource(true);
        return tile.takeSource();
    }

    public void write(HolderLookup.Provider provider, CompoundTag tag) {
        CompoundTag contextTag = new CompoundTag();
        getContext().write(provider, contextTag);
        tag.put("context", contextTag);
    }

    // Called once the ritual tile has created a new instance of this ritual
    public void read(HolderLookup.Provider provider, CompoundTag tag) {
        this.setContext(RitualContext.read(provider, tag.getCompound("context")));
    }

    public @NotNull RitualContext getContext() {
        if (context == null)
            context = new RitualContext();
        return context;
    }

    public void setContext(RitualContext context) {
        this.context = context;
    }

    public abstract ResourceLocation getRegistryName();

    public ParticleColor getCenterColor() {
        return new ParticleColor(
                rand.nextInt(255),
                rand.nextInt(22),
                rand.nextInt(255)
        );
    }

    public ParticleColor getOuterColor() {
        return getCenterColor();
    }

    public int getParticleIntensity() {
        return 10;
    }

    public String getLangName() {
        return "";
    }

    public String getLangDescription() {
        return "";
    }

    /**
     * If this ritual can appear in villager trades
     */
    @Deprecated(since = "4.11.0", forRemoval = true)
    public boolean canBeTraded() {
        return true;
    }

    public void onDestroy() {
    }

    public void onStatusChanged(boolean status) {
    }

    public void modifyTooltips(List<Component> tooltips) {
    }
}

package com.hollingsworth.arsnouveau.api.ritual;

import com.hollingsworth.arsnouveau.api.util.BlockUtil;
import com.hollingsworth.arsnouveau.common.datagen.ItemTagProvider;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceKey;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.biome.Biome;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.Vec3;
import org.jetbrains.annotations.Nullable;

public abstract class ConjureBiomeRitual extends AbstractRitual {
    public int radius = 7;
    public int blocksPlaced;
    public int blocksBeforeSourceNeeded = 5;
    public ResourceKey<Biome> biome;
    public ManhattenTracker tracker;

    public ConjureBiomeRitual(ResourceKey<Biome> biome) {
        super();
        this.biome = biome;
    }

    @Override
    public void onStart(@Nullable Player player) {
        super.onStart(player);
        if (getWorld().isClientSide) {
            return;
        }
        for (ItemStack i : getConsumedItems()) {
            if (i.is(ItemTagProvider.SOURCE_GEM_TAG)) {
                radius += i.getCount();
            }
        }
        tracker = new ManhattenTracker(getPos().below(3), radius, 2, radius);
    }

    @Override
    protected void tick() {
        if (getWorld().isClientSide) {
            return;
        }
        for (int i = 0; i < radius; i++) {
            BlockPos pos = getPos();
            BlockPos nextPos = tracker.computeNext();
            if (nextPos == null) {
                setFinished();
                return;
            }
            double x = nextPos.getX() + 0.5;
            double y = nextPos.getY() + 0.5;
            double z = nextPos.getZ() + 0.5;
            double dist = BlockUtil.distanceFrom(getWorld(), new Vec3(x, y, z), new Vec3(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5));
            if (dist <= radius && getWorld().getBlockState(nextPos).canBeReplaced()) {
                BlockState state = stateForPos(nextPos);
                setState(nextPos, state);
                RitualUtil.changeBiome(getWorld(), nextPos, biome);
                getWorld().playSound(null, nextPos, state.getSoundType().getPlaceSound(), SoundSource.BLOCKS, 1.0f, 1.0f);
                blocksPlaced++;
                if (blocksPlaced >= blocksBeforeSourceNeeded) {
                    blocksPlaced = 0;
                    setNeedsSource(true);
                }
                return;
            }
        }
    }

    @Override
    public boolean canConsumeItem(ItemStack stack) {
        return stack.is(ItemTagProvider.SOURCE_GEM_TAG);
    }

    @Override
    public int getSourceCost() {
        return 50;
    }

    public abstract BlockState stateForPos(BlockPos placePos);

    public void setState(BlockPos pos, BlockState state) {
        getWorld().setBlock(pos, state, 2);
    }

    @Override
    public void read(HolderLookup.Provider provider, CompoundTag tag) {
        super.read(provider, tag);
        if (tag.contains("tracker")) {
            tracker = new ManhattenTracker(tag.getCompound("tracker"));
        }
        radius = tag.getInt("radius");
    }

    @Override
    public void write(HolderLookup.Provider provider, CompoundTag tag) {
        super.write(provider, tag);
        if (tracker != null) {
            tag.put("tracker", tracker.serialize(new CompoundTag()));
        }
        tag.putInt("radius", radius);
    }
}

package com.hollingsworth.arsnouveau.api.ritual;


import com.hollingsworth.arsnouveau.api.ritual.features.IBlockPosProvider;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;

public class ManhattenTracker implements IBlockPosProvider {
    public int i;
    public int j;
    public int k;
    public int l;
    public int pXSize;
    public int pYSize;
    public int pZSize;
    public boolean done;

    public final BlockPos.MutableBlockPos cursor = new BlockPos.MutableBlockPos();
    public int currentDepth;
    public int maxX;
    public int maxY;
    public int x;
    public int y;
    public boolean zMirror;

    public ManhattenTracker(BlockPos pPos, int pXSize, int pYSize, int pZSize) {
        this.i = pXSize + pYSize + pZSize;
        this.j = pPos.getX();
        this.k = pPos.getY();
        this.l = pPos.getZ();
        this.pXSize = pXSize;
        this.pYSize = pYSize;
        this.pZSize = pZSize;
    }

    public CompoundTag serialize(CompoundTag tag) {
        tag.putInt("i", i);
        tag.putInt("j", j);
        tag.putInt("k", k);
        tag.putInt("l", l);
        tag.putInt("pXSize", pXSize);
        tag.putInt("pYSize", pYSize);
        tag.putInt("pZSize", pZSize);
        tag.putBoolean("done", done);
        tag.putInt("currentDepth", currentDepth);
        tag.putInt("maxX", maxX);
        tag.putInt("maxY", maxY);
        tag.putInt("x", x);
        tag.putInt("y", y);
        tag.putBoolean("zMirror", zMirror);
        tag.putInt("cursorX", cursor.getX());
        tag.putInt("cursorY", cursor.getY());
        tag.putInt("cursorZ", cursor.getZ());
        return tag;
    }

    public ManhattenTracker(CompoundTag tag) {
        this.i = tag.getInt("i");
        this.j = tag.getInt("j");
        this.k = tag.getInt("k");
        this.l = tag.getInt("l");
        this.pXSize = tag.getInt("pXSize");
        this.pYSize = tag.getInt("pYSize");
        this.pZSize = tag.getInt("pZSize");
        this.done = tag.getBoolean("done");
        this.currentDepth = tag.getInt("currentDepth");
        this.maxX = tag.getInt("maxX");
        this.maxY = tag.getInt("maxY");
        this.x = tag.getInt("x");
        this.y = tag.getInt("y");
        this.zMirror = tag.getBoolean("zMirror");
        this.cursor.set(tag.getInt("cursorX"), tag.getInt("cursorY"), tag.getInt("cursorZ"));
    }

    public BlockPos computeNext() {
        if (done)
            return null;
        if (this.zMirror) {
            this.zMirror = false;
            this.cursor.setZ(l - (this.cursor.getZ() - l));
            return this.cursor;
        } else {
            BlockPos blockpos;
            for (blockpos = null; blockpos == null; ++this.y) {
                if (this.y > this.maxY) {
                    ++this.x;
                    if (this.x > this.maxX) {
                        ++this.currentDepth;
                        if (this.currentDepth > i) {
                            this.done = true;
                            return null;
                        }

                        this.maxX = Math.min(pXSize, this.currentDepth);
                        this.x = -this.maxX;
                    }

                    this.maxY = Math.min(pYSize, this.currentDepth - Math.abs(this.x));
                    this.y = -this.maxY;
                }

                int i1 = this.x;
                int j1 = this.y;
                int k1 = this.currentDepth - Math.abs(i1) - Math.abs(j1);
                if (k1 <= pZSize) {
                    this.zMirror = k1 != 0;
                    blockpos = this.cursor.set(j + i1, k + j1, l + k1);
                }
            }

            return blockpos;
        }
    }
}

package com.hollingsworth.arsnouveau.api.ritual;

import com.hollingsworth.arsnouveau.api.util.NBTUtil;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.item.ItemStack;

import java.util.ArrayList;
import java.util.List;

public class RitualContext {
    public int progress;
    public boolean isDone;
    public boolean isStarted;
    public boolean needsSourceToRun; // Marks the last time mana was consumed or added.
    public List<ItemStack> consumedItems;

    public RitualContext() {
        progress = 0;
        isDone = false;
        this.isStarted = false;
        consumedItems = new ArrayList<>();
        needsSourceToRun = false;
    }


    public void write(HolderLookup.Provider provider, CompoundTag tag) {
        tag.putInt("progress", progress);
        tag.putBoolean("complete", isDone);
        tag.putBoolean("started", isStarted);
        tag.putBoolean("needsMana", needsSourceToRun);
        NBTUtil.writeItems(provider, tag, "item_", consumedItems);
    }

    public static RitualContext read(HolderLookup.Provider provider, CompoundTag tag) {
        RitualContext context = new RitualContext();
        context.progress = tag.getInt("progress");
        context.isDone = tag.getBoolean("complete");
        context.isStarted = tag.getBoolean("started");
        context.consumedItems = NBTUtil.readItems(provider, tag, "item_");
        context.needsSourceToRun = tag.getBoolean("needsMana");
        return context;
    }
}

package com.hollingsworth.arsnouveau.api.ritual;


import com.hollingsworth.arsnouveau.common.network.ChangeBiomePacket;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Holder;
import net.minecraft.core.QuartPos;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.Mth;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.biome.Biome;
import net.minecraft.world.level.chunk.LevelChunk;
import net.minecraft.world.level.chunk.LevelChunkSection;
import net.minecraft.world.level.chunk.PalettedContainer;
import net.neoforged.neoforge.network.PacketDistributor;

public class RitualUtil {

    /**
     * Provides the next 'closest' position between two positions and an index tracking the last generated position.
     * This is for lazily getting the next closed position between two positions without generating the entire iterator.
     */
    public static BlockPos betweenClosed(int pX1, int pY1, int pZ1, int pX2, int pY2, int pZ2, int index) {
        int i = pX2 - pX1 + 1;
        int j = pY2 - pY1 + 1;
        int k = pZ2 - pZ1 + 1;
        int l = i * j * k;

        int i1 = index % i;
        int j1 = index / i;
        int k1 = j1 % j;
        int l1 = j1 / j;
        return new BlockPos(pX1 + i1, pY1 + k1, pZ1 + l1);
    }

    public static BlockPos betweenClosed(BlockPos pFirstPos, BlockPos pSecondPos, int index) {
        return betweenClosed(Math.min(pFirstPos.getX(), pSecondPos.getX()), Math.min(pFirstPos.getY(), pSecondPos.getY()), Math.min(pFirstPos.getZ(), pSecondPos.getZ()), Math.max(pFirstPos.getX(), pSecondPos.getX()), Math.max(pFirstPos.getY(), pSecondPos.getY()), Math.max(pFirstPos.getZ(), pSecondPos.getZ()), index);
    }

    public static void changeBiome(Level level, BlockPos pos, ResourceKey<Biome> target) {
        Holder<Biome> biome = level.registryAccess().registryOrThrow(Registries.BIOME).getHolderOrThrow(target);
        BlockPos dPos = pos;

        if (level.getBiome(dPos).is(target))
            return;

        int minY = QuartPos.fromBlock(level.getMinBuildHeight());
        int maxY = minY + QuartPos.fromBlock(level.getHeight()) - 1;

        int x = QuartPos.fromBlock(dPos.getX());
        int z = QuartPos.fromBlock(dPos.getZ());

        LevelChunk chunkAt = level.getChunk(dPos.getX() >> 4, dPos.getZ() >> 4);
        for (LevelChunkSection section : chunkAt.getSections()) {
            for (int sy = 0; sy < 16; sy += 4) {
                int y = Mth.clamp(QuartPos.fromBlock(chunkAt.getMinSection() + sy), minY, maxY);
                if (section.getBiomes().get(x & 3, y & 3, z & 3).is(target))
                    continue;
                if (section.getBiomes() instanceof PalettedContainer<Holder<Biome>> container)
                    container.set(x & 3, y & 3, z & 3, biome);
            }
        }

        if (level instanceof ServerLevel server) {
            if (!chunkAt.isUnsaved()) chunkAt.setUnsaved(true);
            ChangeBiomePacket message = new ChangeBiomePacket(pos, target);
            PacketDistributor.sendToPlayersTrackingChunk(server, chunkAt.getPos(), message);
        }
    }
}

package com.hollingsworth.arsnouveau.api.source;

import com.hollingsworth.arsnouveau.api.util.IWololoable;
import com.hollingsworth.arsnouveau.client.particle.ParticleColor;
import com.hollingsworth.arsnouveau.common.block.tile.ModdedTile;
import com.hollingsworth.arsnouveau.common.capability.SourceStorage;
import com.hollingsworth.arsnouveau.common.items.data.BlockFillContents;
import com.hollingsworth.arsnouveau.setup.registry.DataComponentRegistry;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.component.DataComponentMap;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

//TODO: Make relevant source methods final and defaulted in interface
public abstract class AbstractSourceMachine extends ModdedTile implements ISourceTile, IWololoable {

    private ParticleColor color = ParticleColor.defaultParticleColor();
    public static String SOURCE_TAG = "source";
    public static String COLOR_TAG = "color";

    public AbstractSourceMachine(BlockEntityType<?> manaTile, BlockPos pos, BlockState state) {
        super(manaTile, pos, state);
    }

    public @Nullable SourceStorage sourceStorage;

    public @NotNull SourceStorage getSourceStorage() {
        if (sourceStorage == null) {
            sourceStorage = createDefaultStorage();
            if (level != null) level.invalidateCapabilities(worldPosition);
        }
        return sourceStorage;
    }

    @Override
    protected void loadAdditional(@NotNull CompoundTag tag, HolderLookup.@NotNull Provider pRegistries) {
        super.loadAdditional(tag, pRegistries);
        this.sourceStorage = createDefaultStorage();
        if (tag.contains(SOURCE_TAG)) {
            this.sourceStorage.setSource(tag.getInt(SOURCE_TAG));
        }
        color = ParticleColor.fromInt(tag.getInt(COLOR_TAG));
    }

    @Override
    protected void saveAdditional(@NotNull CompoundTag tag, HolderLookup.@NotNull Provider pRegistries) {
        super.saveAdditional(tag, pRegistries);
        tag.putInt(SOURCE_TAG, getSource());
        tag.putInt(COLOR_TAG, getColor().getColor());
    }

    protected @NotNull SourceStorage createDefaultStorage() {
        return new SourceStorage(10000, 1000, 1000, 0) {
            public void onContentsChanged() {
                AbstractSourceMachine.this.updateBlock();
            }
        };
    }

    @Override
    public int setSource(int source) {
        this.getSourceStorage().setSource(Math.clamp(source, 0, this.getMaxSource()));
        updateBlock();
        return this.getSourceStorage().getSource();
    }

    public boolean updateBlock() {
        if (level != null) {
            // force update the capability
            BlockState state = getBlockState();
            level.sendBlockUpdated(worldPosition, state, state, 3);
            setChanged();
            return true;
        }
        return false;
    }

    @Override
    public int addSource(int source, boolean simulate) {
        return getSourceStorage().receiveSource(source, simulate);
    }

    @Override
    public int addSource(int source) {
        return this.setSource(this.getSource() + source);
    }

    @Override
    public int getSource() {
        return this.getSourceStorage().getSource();
    }

    @Override
    public int getTransferRate() {
        return this.getSourceStorage().getMaxExtract();
    }

    @Override
    public int removeSource(int source, boolean simulate) {
        return getSourceStorage().extractSource(source, simulate);
    }

    @Override
    public int removeSource(int source) {
        if (source == 0)
            return this.getSource();
        this.setSource(this.getSource() - source);
        //updateBlock(); updateBlock is called in setSource
        return this.getSource();
    }

    @Override
    public int getMaxSource() {
        return this.getSourceStorage().getSourceCapacity();
    }

    public boolean canAcceptSource() {
        return this.getSource() < this.getMaxSource();
    }

    public boolean canProvideSource() {
        return this.getSource() > 0;
    }

    public boolean canAcceptSource(int source) {
        return this.getSourceStorage().canAcceptSource(source);
    }

    /**
     * Transfers the maximum possible amount of source from one tile to another.
     * Takes the maximum transfer rate of the two tiles into account, and the space remaining.
     *
     * @return The amount of source that was transferred.
     */
    public int transferSource(ISourceTile from, ISourceTile to) {
        int transferRate = getTransferRate(from, to);
        from.removeSource(transferRate);
        to.addSource(transferRate);
        return transferRate;
    }

    /*
     * Transfers the maximum possible amount of source from one SourceStorage to another,
     * checking the transfer rate of the source and destination via simulation.
     */
    public int transferSource(ISourceCap from, ISourceCap to) {
        return transferSource(from, to, from.getMaxExtract());
    }

    public int transferSource(ISourceCap from, ISourceCap to, int amount) {
        int transfer = to.receiveSource(from.extractSource(amount, true), true);
        if (transfer == 0)
            return 0;
        from.extractSource(transfer, false);
        to.receiveSource(transfer, false);
        return transfer;
    }

    /**
     * TODO: 1.22 remove
     * Gets the maximum amount of source that can be transferred from one tile to another.
     */
    @Deprecated(forRemoval = true)
    public int getTransferRate(ISourceTile from, ISourceTile to) {
        return getTransferRate(from, to, from.getTransferRate());
    }

    @Deprecated(forRemoval = true)
    public int getTransferRate(ISourceTile from, ISourceTile to, int fromTransferRate) {
        return Math.min(Math.min(fromTransferRate, from.getSource()), to.getMaxSource() - to.getSource());
    }

    @Deprecated(forRemoval = true)
    public int transferSource(ISourceTile from, ISourceTile to, int fromTransferRate) {
